<?php
require_once dirname(__DIR__,2).'/app/bootstrap.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=(string)($_POST['type']??'');$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');if($id&&in_array($action,['publish','reject','delete'],true)){if($type==='event'){$table='events';}elseif($type==='offer'){$table='offers';}else{$table='';}if($table){if($action==='delete')db()->prepare('DELETE FROM '.$table.' WHERE id=:id')->execute([':id'=>$id]);else{$status=$action==='publish'?'published':'rejected';db()->prepare('UPDATE '.$table.' SET status=:s WHERE id=:id')->execute([':s'=>$status,':id'=>$id]);}flash('success',ucfirst($type).' '.($action==='publish'?'published':($action==='reject'?'rejected':'deleted')).'.');}}redirect(app_path('admin/community.php'));}
$events=db()->query("SELECT e.*,u.name creator FROM events e LEFT JOIN users u ON u.id=e.created_by ORDER BY CASE e.status WHEN 'pending' THEN 0 ELSE 1 END,e.created_at DESC LIMIT 100")->fetchAll();$offers=db()->query("SELECT o.*,l.name listing_name,u.name creator FROM offers o JOIN listings l ON l.id=o.listing_id LEFT JOIN users u ON u.id=o.created_by ORDER BY CASE o.status WHEN 'pending' THEN 0 ELSE 1 END,o.created_at DESC LIMIT 100")->fetchAll();$adminTitle='Events & offers';include __DIR__.'/_header.php';?>
<div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">COMMUNITY CONTENT</span><h2>Event submissions</h2></div></div><?php if($events): ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Event</th><th>When / Where</th><th>Submitted by</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($events as $e): ?><tr><td><strong><?= h($e['title']) ?></strong><small><?= h(text_excerpt($e['description'],120)) ?></small></td><td><?= h($e['starts_at']) ?><small><?= h($e['venue'].' '.$e['location']) ?></small></td><td><?= h($e['creator']??'Unknown') ?></td><td><span class="status-pill status-<?= h($e['status']) ?>"><?= h(ucfirst($e['status'])) ?></span></td><td><div class="row-actions"><?php if($e['status']==='pending'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="type" value="event"><input type="hidden" name="id" value="<?= (int)$e['id'] ?>"><input type="hidden" name="action" value="publish"><button class="table-action">Publish</button></form><form method="post"><?= csrf_field() ?><input type="hidden" name="type" value="event"><input type="hidden" name="id" value="<?= (int)$e['id'] ?>"><input type="hidden" name="action" value="reject"><button class="table-action danger-text">Reject</button></form><?php endif; ?><form method="post" onsubmit="return confirm('Delete this event?')"><?= csrf_field() ?><input type="hidden" name="type" value="event"><input type="hidden" name="id" value="<?= (int)$e['id'] ?>"><input type="hidden" name="action" value="delete"><button class="table-action danger-text">Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="empty-admin">No event submissions yet.</p><?php endif; ?></div>
<div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">BUSINESS PROMOTIONS</span><h2>Offer submissions</h2></div></div><?php if($offers): ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Offer</th><th>Business</th><th>Expiry</th><th>Submitted by</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($offers as $o): ?><tr><td><strong><?= h($o['title']) ?></strong><small><?= h(text_excerpt($o['description'],100)) ?></small></td><td><?= h($o['listing_name']) ?></td><td><?= h($o['ends_at']) ?></td><td><?= h($o['creator']??'Unknown') ?></td><td><span class="status-pill status-<?= h($o['status']) ?>"><?= h(ucfirst($o['status'])) ?></span></td><td><div class="row-actions"><?php if($o['status']==='pending'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="type" value="offer"><input type="hidden" name="id" value="<?= (int)$o['id'] ?>"><input type="hidden" name="action" value="publish"><button class="table-action">Publish</button></form><form method="post"><?= csrf_field() ?><input type="hidden" name="type" value="offer"><input type="hidden" name="id" value="<?= (int)$o['id'] ?>"><input type="hidden" name="action" value="reject"><button class="table-action danger-text">Reject</button></form><?php endif; ?><form method="post" onsubmit="return confirm('Delete this offer?')"><?= csrf_field() ?><input type="hidden" name="type" value="offer"><input type="hidden" name="id" value="<?= (int)$o['id'] ?>"><input type="hidden" name="action" value="delete"><button class="table-action danger-text">Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="empty-admin">No offer submissions yet.</p><?php endif; ?></div><?php include __DIR__.'/_footer.php';?>
